"use client";

import { MorphingAccordion } from "@/components/application/animations/expanded/controls/morphing-accordion";

export default function Example() {
  return (
    <MorphingAccordion
      defaultValue={[
        "frames"
      ]}
      items={[
        {
          "id": "frames",
          "question": "Can I bring my own questions and answers?",
          "answer": "Each item accepts a question and any React content as its answer. Add paragraphs, helpful links, or another small component. The surrounding surface measures the answer and grows to fit, while the question stays readable throughout the transition."
        },
        {
          "id": "trainers",
          "question": "How does the expanding answer stay connected?",
          "answer": "A separate decorative layer follows the question and answer surfaces. Their shapes briefly join as the answer opens, then settle into two rounded panels. The text stays outside the liquid filter."
        },
        {
          "id": "left",
          "question": "Can several answers remain open at once?",
          "answer": "Enable the multiple option to keep several answers open. You can also provide a controlled array of item IDs and synchronize the expanded answers with the rest of your application."
        },
        {
          "id": "warranty",
          "question": "Does the control work with a keyboard?",
          "answer": "Every question is a real button. Use Tab to focus it, then press Enter or Space to expand the answer. The button reports its expanded state to assistive technology."
        },
        {
          "id": "custom",
          "question": "Can I change the colors and motion speed?",
          "answer": "Pass a surface color, text color, and duration to match your interface. People who prefer reduced motion get the same answers and controls with immediate state changes."
        }
      ]}
      duration={0.65}
      background={"#111111"}
      color={"#eeece8"}
      goo={18}
      multiple={false}
      showNumbers={true}
    />
  );
}

