"use client";
import { useId, useRef, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import {
  ControlLiquid,
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MorphingAccordionItem {
  id: string;
  question: string;
  answer: ReactNode;
  disabled?: boolean;
}
export interface MorphingAccordionProps extends ControlAppearance {
  items: readonly MorphingAccordionItem[];
  value?: readonly string[];
  defaultValue?: readonly string[];
  onValueChange?: (value: string[]) => void;
  multiple?: boolean;
  goo?: number;
  showNumbers?: boolean;
}
export function MorphingAccordion({
  items,
  value,
  defaultValue = [],
  onValueChange,
  multiple = false,
  goo = 18,
  showNumbers = true,
  ...appearance
}: MorphingAccordionProps) {
  const [selected, setSelected] = useControlValue<readonly string[]>(value, defaultValue, (v) =>
    onValueChange?.([...v]),
  );
  const id = useId();
  const transition = useControlTransition(appearance.duration);
  return (
    <>
      <ControlStyles />
      <div
        className={`z-mc z-mc-accordion ${appearance.className ?? ""}`}
        style={controlVariables(appearance)}
      >
        {items.map((item, index) => (
          <AccordionItem
            key={item.id}
            item={item}
            index={index}
            id={id}
            open={selected.includes(item.id)}
            toggle={() =>
              setSelected(
                selected.includes(item.id)
                  ? selected.filter((v) => v !== item.id)
                  : multiple
                    ? [...selected, item.id]
                    : [item.id],
              )
            }
            showNumbers={showNumbers}
            goo={goo}
            duration={appearance.duration}
            transition={transition}
          />
        ))}
      </div>
    </>
  );
}
function AccordionItem({
  item,
  index,
  id,
  open,
  toggle,
  showNumbers,
  goo,
  duration,
  transition,
}: {
  item: MorphingAccordionItem;
  index: number;
  id: string;
  open: boolean;
  toggle: () => void;
  showNumbers: boolean;
  goo: number;
  duration?: number;
  transition: ReturnType<typeof useControlTransition>;
}) {
  const root = useRef<HTMLDivElement>(null);
  return (
    <motion.div layout className="z-mc-accordion-item" ref={root} transition={transition}>
      <ControlLiquid root={root} revision={open} goo={goo} duration={duration} />
      <h3>
        <button
          type="button"
          id={`${id}-${item.id}-trigger`}
          className="z-mc-pill z-mc-accordion-trigger"
          data-z-mc-liquid="question"
          aria-expanded={open}
          aria-controls={`${id}-${item.id}-answer`}
          disabled={item.disabled}
          onClick={toggle}
        >
          {showNumbers && (
            <span className="z-mc-accordion-index">{String(index + 1).padStart(2, "0")}</span>
          )}
          <span>{item.question}</span>
          <motion.span
            className="z-mc-accordion-plus"
            aria-hidden="true"
            animate={{ rotate: open ? 45 : 0 }}
            transition={transition}
          >
            +
          </motion.span>
        </button>
      </h3>
      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            className="z-mc-accordion-answer-wrap"
            initial={{ height: 0 }}
            animate={{ height: "auto" }}
            exit={{ height: 0 }}
            transition={transition}
          >
            <div
              className="z-mc-accordion-answer"
              id={`${id}-${item.id}-answer`}
              role="region"
              aria-labelledby={`${id}-${item.id}-trigger`}
              data-z-mc-liquid="answer"
            >
              <span className="z-mc-neck" aria-hidden="true" />
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -8 }}
                transition={{
                  ...transition,
                  delay: open ? Number(transition.duration ?? 0) * 0.14 : 0,
                }}
              >
                {item.answer}
              </motion.div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
